// Curated USDA FoodData Central records for the bundled seed catalog.
// Each entry pins an FDC id AND the exact USDA description; build-seed.mjs fails if either drifts.
//
// Alias policy (see docs/DATA_SOURCES.md):
// - Aliases are names people actually search: English, Hindi/regional names in Latin transliteration
//   (common spelling variants), and native-script names only where the curator was confident.
// - Never alias two different foods as equivalent. When USDA's record is close but not identical
//   to the Indian item (whole vs split dal, US vs Indian variety, related but different species),
//   that is said in `notes`, and the Indian name is only used as an alias if it is the same food.
// - Deliberately NOT aliased (different foods): poha (USDA "poha" = cape gooseberry), makhana
//   (fox nut, not lotus seed), tej patta (not bay laurel), suran/jimikand (not Dioscorea yam),
//   ber (Indian jujube, not Chinese jujube), amla (not European gooseberry), jaggery (not brown
//   sugar), chaas (not US cultured buttermilk), toned milk (not US 2% milk), rohu/catla/hilsa/
//   surmai/bangda/pomfret (not the USDA species), chana dal (split desi chickpea, no USDA record).

const sr = (fdcId, desc, name, tags, aliases = [], extra = {}) => ({ dataset: 'sr_legacy', fdcId, desc, name, tags, aliases, ...extra });
const fo = (fdcId, desc, name, tags, aliases = [], extra = {}) => ({ dataset: 'foundation', fdcId, desc, name, tags, aliases, ...extra });
const su = (fdcId, desc, name, tags, aliases = [], extra = {}) => ({ dataset: 'survey', fdcId, desc, name, tags, aliases, ...extra });

const WHOLE_DAL_NOTE = 'USDA record is the whole mature seed; split, dehusked dal is close in energy and protein but has less fibre.';

